// Valider les parametres
const input = $input.first().json;
const query = input.query || {};

const projectId = query.project_id || null;

if (!projectId) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Le parametre "project_id" est requis',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    project_id: projectId
  }
}];

// Verifier que le projet existe dans Redis
const redisResult = $('Get Stripe Config (Redis)').first();
const inputData = $('Validate Input').first().json;

// Verifier si Redis a retourne une erreur
const redisJson = redisResult?.json || {};
if (redisJson.error || redisJson.message?.includes('ECONNREFUSED')) {
  return [{
    json: {
      found: false,
      error: {
        code: 503,
        message: 'Service Redis indisponible',
        status: 'SERVICE_UNAVAILABLE'
      }
    }
  }];
}

// Redis retourne la valeur dans propertyName, value, ou directement
const rawValue = redisJson.propertyName || redisJson.value || redisJson;

if (!rawValue || rawValue === null || rawValue === 'null') {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Projet '${inputData.project_id}' non enregistre. Appelez /stripe-register-project d'abord.`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

// Parser le JSON stocke dans Redis
let project;
try {
  project = typeof rawValue === 'string' ? JSON.parse(rawValue) : rawValue;
} catch (e) {
  return [{
    json: {
      found: false,
      error: {
        code: 500,
        message: `Erreur parsing Redis: ${e.message}`,
        status: 'INTERNAL_ERROR'
      }
    }
  }];
}

if (!project.stripe_key) {
  return [{
    json: {
      found: false,
      error: {
        code: 404,
        message: `Projet '${inputData.project_id}' n'a pas de cle Stripe configuree`,
        status: 'NOT_FOUND'
      }
    }
  }];
}

return [{
  json: {
    found: true,
    project_id: inputData.project_id,
    display_name: project.display_name || inputData.project_id,
    secret_key: project.stripe_key
  }
}];

// Formater les plans depuis la reponse Stripe (products avec default_price)
const input = $input.first().json;
const projectData = $('Check Project').first().json;

const statusCode = input.statusCode || 200;
const data = input.body || input;

// Verifier les erreurs Stripe
if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || 'Erreur Stripe API',
        status: 'STRIPE_ERROR'
      }
    }
  }];
}

const products = data.data || [];

// Formater les plans depuis les produits actifs
const plans = products
  .filter(product => product.default_price) // Exclure produits sans prix
  .map(product => {
    const price = product.default_price || {};

    // Extraire les features depuis les metadata du produit
    let features = [];
    if (product.metadata?.features) {
      try {
        features = JSON.parse(product.metadata.features);
      } catch (e) {
        features = product.metadata.features.split(',').map(f => f.trim());
      }
    }

    // Extraire credits_per_month depuis metadata
    const creditsPerMonth = parseInt(product.metadata?.credits_per_month || price.metadata?.credits_per_month || '0');

    return {
      id: price.id,
      product_id: product.id,
      name: product.name || 'Plan',
      description: product.description || null,
      price: (price.unit_amount || 0) / 100,
      currency: price.currency || 'eur',
      interval: price.recurring?.interval || 'month',
      interval_count: price.recurring?.interval_count || 1,
      credits_per_month: creditsPerMonth,
      features: features,
      metadata: {
        ...product.metadata,
        ...price.metadata
      }
    };
  });

// Trier par prix
plans.sort((a, b) => a.price - b.price);

return [{
  json: {
    success: true,
    project_id: projectData.project_id,
    project_name: projectData.display_name,
    plans_count: plans.length,
    plans: plans
  }
}];
